import {packCargoSafeRedToBits} from './cargo-safe-mask.mjs';
import {sha256,stableJSON} from '../compatibility/codec.mjs';
import {createThreeSceneRegistry,verifyThreeSceneRegistry,verifySelectedSceneMaterial} from './cargo-three-scene-geometry.mjs';
import {TWO_SCENE_REGISTRATION as R,TWO_SCENE_MANIFEST_SHA,ORIGINAL_TWO_SPECS} from './cargo-next-two-registration.mjs';
const REVISION='CARGO_FIVE_SCENE_SELECTED_FLOORS_R2_BRIDGE_R4_20261029',PREVIOUS_REVISION='CARGO_THREE_SCENE_SELECTED_FLOORS_R2_BRIDGE_R4_20261029';
const ownBytes=v=>{if(v instanceof ArrayBuffer)return new Uint8Array(v.slice(0));if(v instanceof Uint8Array)return new Uint8Array(v);throw Error('FLOOR_BYTE_TYPE')};
const byteHash=async b=>[...new Uint8Array(await crypto.subtle.digest('SHA-256',b))].map(v=>v.toString(16).padStart(2,'0')).join('');
const pin=p=>({...p,path:'next-two-r1/'+p.path});
const geometryFor=id=>({revision:R.revision,manifestSHA:TWO_SCENE_MANIFEST_SHA,selectionSHA:R.selection.sha256,states:Object.fromEntries(Object.entries(R.scenes[id].states).map(([k,v])=>[k,pin(v.safe)])),doorBitOrder:R.scenes[id].doorBitOrder,excluded:R.scenes[id].excludedSpawnWarpSaveNPC.map(r=>r.boundsHalfOpen)});
const closed=id=>Object.keys(R.scenes[id].states).at(-1),materials=new WeakMap();
export function createFiveSceneRegistry(base){const r=createThreeSceneRegistry(base);r.revision=REVISION;for(const id of Object.keys(R.scenes)){r.scenes[id].geometry=geometryFor(id);r.scenes[id].footCenters=pin(R.scenes[id].states[closed(id)].safe)}return r;}
export function verifyFiveSceneRegistry(input){try{const r=structuredClone(input);if(r.revision!==REVISION)return false;for(const id of Object.keys(R.scenes)){const expected={...structuredClone(ORIGINAL_TWO_SPECS[id]),geometry:geometryFor(id),footCenters:pin(R.scenes[id].states[closed(id)].safe)};if(stableJSON(r.scenes[id])!==stableJSON(expected))return false;r.scenes[id]=structuredClone(ORIGINAL_TWO_SPECS[id])}r.revision=PREVIOUS_REVISION;return verifyThreeSceneRegistry(r)}catch{return false}}
export function nextSceneState(id,doors){const order=R.scenes[id]?.doorBitOrder;if(!order)return null;return 'doors_'+(order.map(key=>doors?.[key]?.phase==='open'&&doors[key].progress===1?'0':'1').join('')||'none')}
export function nextSceneAllowsPlacement(id,foot,purpose='movement'){if(!Object.hasOwn(R.scenes,id)||!['movement','spawn','warp','save','npc'].includes(purpose)||!Array.isArray(foot)||foot.length!==2||!foot.every(Number.isInteger))return false;const[x,y]=foot;return x>=0&&x<1536&&y>=0&&y<1024&&!R.scenes[id].excludedSpawnWarpSaveNPC.some(({boundsHalfOpen:[l,t,r,b]})=>x>=l&&x<r&&y>=t&&y<b)}
export async function createNextSelectedSceneMaterial({spec,readBytes,decodeMask,decodeArt,readDoors,dispose=()=>{}}){
 const id=spec?.sceneId,g=R.scenes[id];if(!g||stableJSON(spec.geometry)!==stableJSON(geometryFor(id))||spec.art.sha256!==g.sourceImageSHA256||typeof readDoors!=='function'||typeof decodeArt!=='function')throw Error('SELECTED_FLOOR_REGISTRATION');
 const registered=geometryFor(id),specSignature=stableJSON(spec);
 const artBytes=ownBytes(await readBytes(spec.art.path));if(await byteHash(artBytes)!==g.sourceImageSHA256)throw Error('SELECTED_IMAGE_SHA');const masks={};
 for(const[state,pin]of Object.entries(registered.states)){const bytes=ownBytes(await readBytes(pin.path));if(await byteHash(bytes)!==pin.sha256)throw Error('SELECTED_MASK_SHA');const mask=await decodeMask(bytes);if(mask.width!==1536||mask.height!==1024||!(mask.data instanceof Uint8Array||mask.data instanceof Uint8ClampedArray)||mask.data.length!==1536*1024*4)throw Error('SELECTED_MASK_DECODE');masks[state]=packCargoSafeRedToBits(mask.data)}
 for(const[path,hash]of [['next-two-r1/ROOT_SELECTION.json',R.selection.sha256],['next-two-r1/SELECTED_NEXT_TWO_RUNTIME_MANIFEST.json',TWO_SCENE_MANIFEST_SHA]])if(await byteHash(ownBytes(await readBytes(path)))!==hash)throw Error('SELECTED_SELECTION_SHA');
 const art=await decodeArt(artBytes);if(!art||art.width!==1536||art.height!==1024){art?.close?.();throw Error('SELECTED_IMAGE_DIMENSIONS')}let dead=false;const state=()=>nextSceneState(id,readDoors());
 const m={sceneId:id,artSHA256:g.sourceImageSHA256,width:1536,height:1024,art,get maskStorageBytes(){return Object.values(masks).reduce((n,a)=>n+a.byteLength,0)},geometryRevision:R.revision,geometryManifestSHA:TWO_SCENE_MANIFEST_SHA,get geometryState(){return state()},get footMaskSHA256(){return registered.states[state()].sha256},isSafeFoot(foot){if(dead||!nextSceneAllowsPlacement(id,foot))return false;const i=foot[1]*1536+foot[0];return (masks[state()][i>>>3]&(1<<(i&7)))!==0},allowsPlacement(foot,purpose){return nextSceneAllowsPlacement(id,foot,purpose)&&m.isSafeFoot(foot)},dispose(){if(!dead){dead=true;for(const key of Object.keys(masks))delete masks[key];try{art.close?.()}finally{dispose()}}}};materials.set(m,{spec:specSignature,live:()=>!dead});return Object.freeze(m);
}
export function verifyFiveSceneMaterial(spec,m){if(!Object.hasOwn(R.scenes,spec.sceneId))return verifySelectedSceneMaterial(spec,m);const p=materials.get(m);return !!p&&p.live()&&p.spec===stableJSON(spec)&&m.footMaskSHA256===spec.geometry.states[m.geometryState]?.sha256;}
